SINA_SMART["viro1-hpv"] = {"lecture":"viro1-hpv","title":"Human papillomavirus (HPV)","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"viro1-hpv:e3","text":"HPV DNA in 99.7% of cervical cancers (zur Hausen, Nobel 2008).","topic":"History","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"viro1-hpv:e7","text":"Koilocytes are the cytological hallmark of HPV infection.","topic":"History","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"viro1-hpv:e0","text":"HPV: naked, icosahedral, circular dsDNA, 45-55 nm.","topic":"The virus","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"viro1-hpv:e1","text":"More than 200 genotypes; cutaneous or mucosal tropism.","topic":"The virus","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"viro1-hpv:e2","text":"High-risk 16 and 18 → cervical cancer; low-risk 6 and 11 → warts.","topic":"Diseases","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"viro1-hpv:e4","text":"CIN 1 → CIN 2/3 → invasive cancer over 7-30 years.","topic":"Diseases","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"viro1-hpv:e5","text":"Screening: Pap smear cytology and HPV DNA test.","topic":"Screening and diagnosis","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"viro1-hpv:e6","text":"Vaccines are VLPs of L1 protein: 2-valent, 4-valent, 9-valent.","topic":"Vaccination","sec":4,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"djwa2z":"a","343cv0":"a","uxju0g":"a","18cdjtm":"a","e7t6kn":"a","10vo92r":"a","wf0td2":"a","141gbuv":"a","1egf06n":"a","184y461":"a","v3ls8q":"a","n8hgf7":"x"},"mapCounts":{"verified":0,"auto":11,"ambiguous":0,"missing":1},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"viro1-hpv:e3":{"s":0,"u":["HPV DNA in 99.7% of cervical cancers (zur Hausen, Nobel 2008).","In 1975-76 Meisels described koilocytes in precancerous lesions and Harald zur Hausen linked cervical cancer to papillomavirus (Nobel Prize 2008).","Genotypes were split into high risk (cancer) and low risk (warts) around 1980, and in 1999 HPV DNA was found in 99.7% of cervical cancers."],"dp":[]},"viro1-hpv:e7":{"s":0,"u":["Koilocytes are the cytological hallmark of HPV infection."],"dp":[]},"viro1-hpv:e0":{"s":1,"u":["HPV: naked, icosahedral, circular dsDNA, 45-55 nm.","Family Papillomaviridae (genus alpha-papillomavirus for the genital types): naked (non-enveloped), icosahedral , small (45-55 nm), with circular double-stranded DNA ."],"dp":[]},"viro1-hpv:e1":{"s":1,"u":["More than 200 genotypes; cutaneous or mucosal tropism.","There are more than 200 genotypes , classified by sequence, by tropism (cutaneous, mucosal, mixed) and by oncogenic potential : high-risk (16, 18, 31, 33, 45, 52, 58...) and low-risk (6, 11: warts and condylomas)."],"dp":[]},"viro1-hpv:e2":{"s":2,"u":["High-risk 16 and 18 → cervical cancer; low-risk 6 and 11 → warts.","Anogenital warts (condylomata acuminata) : low-risk types 6 and 11.","Cervical cancer : persistent high-risk infection progresses from CIN 1 (about half regress) to CIN 2/3 to invasive cancer over 7-30 years ."],"dp":[{"h":"How E6 and E7 turn a cell cancerous","t":"High-risk HPV types make two oncoproteins. E6 marks the tumour suppressor p53 for destruction, so damaged cells no longer stop or die. E7 binds and inactivates the retinoblastoma protein (Rb), releasing the brake on the cell cycle. When the viral DNA integrates into the host genome, E6 and E7 are often over-expressed, pushing the cell towards cancer. Low-risk types 6 and 11 make weaker versions, which is why they cause warts, not cancer."}]},"viro1-hpv:e4":{"s":2,"u":["CIN 1 → CIN 2/3 → invasive cancer over 7-30 years.","Cervical cancer : persistent high-risk infection progresses from CIN 1 (about half regress) to CIN 2/3 to invasive cancer over 7-30 years ."],"dp":[]},"viro1-hpv:e5":{"s":3,"u":["Screening: Pap smear cytology and HPV DNA test.","Cytology (Pap smear) looks for abnormal cervical cells; HPV DNA testing (PCR-based) detects high-risk types and is increasingly used as the primary screening test."],"dp":[]},"viro1-hpv:e6":{"s":4,"u":["Vaccines are VLPs of L1 protein: 2-valent, 4-valent, 9-valent."],"dp":[]}},"meta":{"djwa2z":{"a":"recall","vg":"viro1-hpv:e0/recall/1"},"343cv0":{"a":"recall","vg":"viro1-hpv:e3/recall/1"},"uxju0g":{"a":"relationship","vg":"viro1-hpv:e2/relationship/1"},"18cdjtm":{"a":"recall","vg":"viro1-hpv:e7/recall/1"},"e7t6kn":{"a":"recall","vg":"viro1-hpv:e3/recall/2"},"10vo92r":{"a":"recall","vg":"viro1-hpv:e6/recall/1"},"wf0td2":{"a":"recall","vg":"viro1-hpv:e6/recall/2"},"141gbuv":{"a":"recall","vg":"viro1-hpv:e4/recall/1"},"1egf06n":{"a":"recall","vg":"viro1-hpv:e5/recall/1"},"184y461":{"a":"recall","vg":"viro1-hpv:e4/recall/2"},"v3ls8q":{"a":"recall","vg":"viro1-hpv:e5/recall/2"}},"explRev":"26f739a87c2b"};
